    "number": 42,
    "complex": 3 + 4j,
    "timestamp": datetime.datetime(2023, 10, 25, 14, 30, 45)
}

# Encode data to JSON
encoded_json = custom_dumps(data)
print(encoded_json)  # Output should be a JSON string with complex and datetime objects properly encoded.

# Decode JSON back to Python object
