import json
from datetime import datetime

class CustomJSONEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, complex):
            return {"real": obj.real, "imag": obj.imag}
        if isinstance(obj, datetime):
            return {
                "year": obj.year, "month": obj.month, "day": obj.day,
                "hour": obj.hour, "minute": obj.minute, "second": obj.second
            }
        return super().default(obj)

def custom_json_decoder(dct):
    if "real" in dct and "imag" in dct:
        return complex(dct["real"], dct["imag"])
    if all(k in dct for k in ("year", "month", "day", "hour", "minute", "second")):
        return datetime(dct["year"], dct["month"], dct["day"], dct["hour"], dct["minute"], dct["second"])
    return dct

def custom_dumps(obj, **kwargs):
    return json.dumps(obj, cls=CustomJSONEncoder, **kwargs)

def custom_loads(s, **kwargs):
    return json.loads(s, object_hook=custom_json_decoder, **kwargs)
```

