class Autoloader {
    static function register() {
        spl_autoload_register(array(__CLASS__, 'autoload'));
    }

    static function autoload($fqcn) {
        $path = str_replace('\\', DIRECTORY_SEPARATOR, $fqcn);
        $rootNamespace = 'Classes';

        if (strpos($path, $rootNamespace) === 0) {
            $path = substr($path, strlen($rootNamespace));
            $file = __DIR__ . DIRECTORY_SEPARATOR . trim($path, DIRECTORY_SEPARATOR) . '.php';

            if (file_exists($file)) {
                require $file;
            } else {
                throw new Exception("Class file not found: $file");
            }
        }
    }
}
