namespace Classes\Form;

abstract class GenericFormQuestion implements QuestionInterface {
    private string $uuid;
    private string $type;
    private string $label;
    private mixed $correct;
    private mixed $userResponse;
    private ?array $choices;

    public function __construct(string $uuid, string $type, string $label, ?array $choices, mixed $correct) {
        $this->uuid = $uuid;
        $this->type = $type;
        $this->label = $label;
        $this->choices = $choices;
        $this->correct = $correct;
        $this->userResponse = null;
    }

    public function getUuid(): string {
        return $this->uuid;
    }

    public function getType(): string {
        return $this->type;
    }

    public function getLabel(): string {
        return $this->label;
    }

    public function getCorrect(): mixed {
        return $this->correct;
    }

    public function getUserResponse(): mixed {
        return $this->userResponse;
    }

    public function setUserResponse(mixed $userResponse): void {
        $this->userResponse = $userResponse;
    }

    public function getChoices(): ?array {
        return $this->choices;
    }

    abstract public function isCorrect(): bool;

    abstract public function render(): string;
}
