final class CheckboxQuestion extends GenericFormQuestion {

    public function __construct(string $uuid, string $type, string $label, array $choices, array $correct) {
        parent::__construct($uuid, $type, $label, $choices, $correct);
    }

    public function isCorrect(): bool {
        $userResponse = $this->getUserResponse();
        if (empty($userResponse)) {
            return false;
        }
        $diff1 = array_diff($this->getCorrect(), $userResponse);
        $diff2 = array_diff($userResponse, $this->getCorrect());

        return count($diff1) == 0 && count($diff2) == 0;
    }

    public function render(): string {
        $choices = $this->getChoices();
        $html = sprintf(
            '<div class="form-group">
                <label for="question-%s">%s</label>
                <div class="form-check">',
            $this->getUuid(),
            $this->getLabel()
        );

        foreach($choices as $choice){
            $html .= sprintf(
                '<input type="checkbox" class="form-check-input" id="question-%s-%s" name="question-%s[]" value="%s">
                <label class="form-check-label" for="question-%s-%s">%s</label>',
                $this->getUuid(),
                $choice,
                $this->getUuid(),
                $choice,
                $this->getUuid(),
                $choice,
                $choice
            );
        }

        $html .= '</div></div><br>';
        return $html;
    }

}
